  "noticeReopen": "Meddelelse om lagring",
  "noticeLabel": "Meddelelse om browserlagring",
  "noticeText": "Cook bruger browserlagring til de madlavnings- og loginfunktioner, du bruger. Der tilføjes ingen lagring til annoncer eller analyse.",
  "noticeClose": "Luk meddelelse om lagring",
  "privDraftLabel": "Udkast – opdateret 28. oktober 2026.",
  "privDraft": "Kontofunktionerne er under test. Oplysningerne om den dataansvarlige og tjenesterne nedenfor skal udfyldes før den offentlige lancering.",
  "privWho1": "Cook drives af [den dataansvarliges juridiske navn og postadresse]. Kontakt [e-mailadresse til privatlivsspørgsmål] med spørgsmål og anmodninger om privatliv. Disse oplysninger skal udfyldes, før registreringen åbner.",
  "privWhat1": "Når du opretter en konto, bruger vi din e-mail, et konto-id, oplysninger om adgangskodegodkendelse og bekræftelsesstatus til at levere og beskytte din konto. Adgangskoder håndteres af godkendelsesudbyderen som sikre hashes; Cook gemmer ingen læsbare adgangskoder. Vi gemmer køkkenets indretning, valgt sprog, tema og måleenheder for at gendanne dine indstillinger på tværs af enheder. Du skal angive e-mail og adgangskode for at have en konto; du kan se opskrifter uden.",
  "privWhat2": "Behandling af konto og indstillinger er nødvendig for at levere den kontotjeneste, du beder om (databeskyttelsesforordningens artikel 6, stk. 1, litra b). Begrænsede sikkerheds- og misbrugsforebyggende oplysninger kan behandles på grundlag af legitime interesser (artikel 6, stk. 1, litra f), i det omfang det er nødvendigt og efter en afvejning. Mails om bekræftelse og nulstilling af adgangskode er servicebeskeder, ikke markedsføring. Kontofunktionen tilføjer ingen annoncer eller analyse.",
  "privStorage1": "Cook bruger sessionStorage til at tage dit køkken, din fremgang i madlavningen og dine valg med mellem sider i samme fane. Når du er logget ind, indeholder den også din login-session. Browseren rydder normalt dette, når fanens session slutter, men browserens gendannelse af sessioner kan bevare det. Når du logger ud, ryddes Cooks fanedata. Lukningen af meddelelsen om lagring gemmes kun i den fane. Cooks egne scripts sætter ingen cookies. Dine hosting- eller tjenesteudbydere kan have deres egen sikkerhedsbehandling, som skal dokumenteres før lanceringen.",
  "privStorage2": "OK og lukkeknappen på meddelelsen om lagring lukker kun meddelelsen. De giver ikke tilladelse til analyse, annoncer eller anden valgfri sporing. Fremtidig ikke-nødvendig lagring kræver et særskilt valg, før den starter, med lige så let afvisning og tilbagetrækning.",
  "privOther1": "Den nuværende talefunktion i opskriftslisten spørger country.is om et omtrentligt land ud fra din IP-adresse for at vælge talesprog. Hvis du bruger mikrofongenkendelse, kan din browser sende lyd til sin talegenkendelsesudbyder. Du kan også skrive ingredienserne. Disse udbydere, deres politikker og retsgrundlaget for funktionerne skal gennemgås før den offentlige lancering.",
  "privProviders1": "Planlagt kontoudbyder: Supabase (administreret PostgreSQL og godkendelse) med en valgt databaseregion i EU. E-mailudbyder: [udbyder]. Webhosting: [udbyder]. Den dataansvarlige skal bekræfte de faktiske udbydere, databehandleraftaler, underdatabehandlere, placering af logfiler og eventuelle overførsler uden for EØS. En databaseregion i EU udelukker ikke i sig selv internationale overførsler. Angiv i givet fald den relevante tilstrækkelighedsafgørelse eller de kontraktlige garantier, og hvordan man får en kopi.",
  "privRetention1": "Kontoindstillinger opbevares, så længe din konto er aktiv. Du kan anmode om sletning via privatlivskontakten ovenfor. Før lanceringen skal den dataansvarlige fastlægge, hvordan sletteanmodninger håndteres, hvornår ubekræftede konti udløber, og hvor længe sikkerhedslogs og sikkerhedskopier opbevares. Slettede data kan forblive i adgangsbegrænsede sikkerhedskopier, indtil den dokumenterede opbevaringsperiode udløber.",
  "privRights1": "Afhængigt af de gældende betingelser kan du anmode om indsigt, berigtigelse, sletning, begrænsning eller dataportabilitet eller gøre indsigelse mod behandling på grundlag af legitime interesser. Kontakt den dataansvarlige ovenfor; anmodninger besvares normalt inden for en måned, og en eventuel lovlig forlængelse forklares. Du kan klage til din tilsynsmyndighed, herunder den ungarske NAIH på naih.hu. Cook bruger ikke kontoindstillinger til automatiske afgørelser med retsvirkning eller tilsvarende betydelige følger.",
